import{_ as e,o as s,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"First portfolio sync","description":"What is imported on first sync, freshness states, source errors, manual-data handling, and where to verify results.","frontmatter":{"title":"First portfolio sync","description":"What is imported on first sync, freshness states, source errors, manual-data handling, and where to verify results.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"get-started/first-portfolio-sync.md","filePath":"get-started/first-portfolio-sync.md","lastUpdated":null}'),n={name:"get-started/first-portfolio-sync.md"};function a(i,t,l,d,c,u){return s(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="first-portfolio-sync" tabindex="-1">First portfolio sync</h1><p>After you connect a data source, Zenin imports your portfolio so research and decisions stay connected to what you actually hold.</p><h2 id="what-is-imported" tabindex="-1">What is imported</h2><p>On first sync Zenin imports:</p><ul><li><strong>Holdings</strong> — positions, quantities, and instrument metadata.</li><li><strong>Balances</strong> — cash and account balances where the source provides them.</li><li><strong>Executions</strong> — completed trades, used to build trade records and the journal.</li><li><strong>Account context</strong> — which source each position came from, for attribution.</li></ul><p>Manual positions and journal entries you create are kept separately and shown alongside connected data.</p><h2 id="freshness-states" tabindex="-1">Freshness states</h2><p>Every imported item carries a freshness state. You will see one of:</p><ul><li><strong>Current</strong> — recently refreshed from the source.</li><li><strong>Delayed</strong> — the source provides data on a delay.</li><li><strong>Stale</strong> — the last successful refresh is older than expected.</li><li><strong>Unavailable</strong> — the source did not return data.</li><li><strong>Reference-only</strong> — descriptive data, not a live price.</li></ul><p>See the <a href="/use-zenin/data-status-glossary">Data status glossary</a> for the full list and meanings.</p><h2 id="source-errors" tabindex="-1">Source errors</h2><p>If a source errors during sync:</p><ul><li>The affected positions keep their <strong>last known</strong> state and are marked accordingly.</li><li>A <strong>source-health notice</strong> may appear in Notifications.</li><li>Zenin retries per the source&#39;s retry behavior; it does not invent missing data.</li></ul><h2 id="manual-data-handling" tabindex="-1">Manual-data handling</h2><p>When a source cannot provide a value (or you want to track something outside a connection):</p><ul><li>Add a <strong>manual position</strong> from Portfolio.</li><li>It is attributed as <strong>manual</strong> so it is never confused with connected data.</li><li>Manual and connected totals are reconciled in the unified view, with <strong>duplicate-exposure warnings</strong> when the same instrument appears in more than one source.</li></ul><h2 id="where-to-verify-results" tabindex="-1">Where to verify results</h2><ul><li><strong>Portfolio</strong> — holdings, totals, source attribution, and freshness per position.</li><li><strong>Portfolio activity</strong> — recent imports and sync events.</li><li><strong>Notifications</strong> — source-health and sync notices.</li></ul><p><strong>Next:</strong> <a href="/get-started/set-up-your-workspace">Set up your workspace</a></p>',19)])])}const f=e(n,[["render",a]]);export{h as __pageData,f as default};
